CREATE OR REPLACE FUNCTION public.action_case_item_cost_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer; v_known boolean; v_verified boolean; v_work_count integer; v_own boolean; v_sub boolean; v_has_sub boolean; v_material boolean; v_other boolean;
begin
  with effective as (
    select l.*, case when l.pricing_method='quotes' and (q.id is null or not q.checked
      or q.scope_snapshot <> coalesce(new.scope,'') or q.description_snapshot <> l.description
      or (q.valid_until is not null and q.valid_until < (now() at time zone 'Europe/Stockholm')::date))
      then false else l.is_verified end as valid
    from public.action_case_cost_lines l left join public.action_case_work_quotes q on q.id=l.selected_quote_id and q.cost_line_id=l.id
    where l.action_case_item_id=new.id and l.org_id=new.org_id and l.covered_by_quote_id is null
  ) select count(*), bool_and(quantity is not null and unit_cost is not null and (pricing_method <> 'quotes' or valid)), bool_and(valid),
    round(sum(quantity*unit_cost),2), round(sum(quantity*unit_cost*(1+markup_percent/100)),2),
    count(*) filter (where category in ('own_labor','subcontractor')),
    bool_and(valid) filter (where category='own_labor'), bool_and(valid) filter (where category='subcontractor'),
    bool_or(category='subcontractor'), bool_and(valid) filter (where category='material'),
    bool_and(valid) filter (where category in ('waste','transport','other'))
  into v_count,v_known,v_verified,new.estimated_cost,new.customer_price,v_work_count,v_own,v_sub,v_has_sub,v_material,v_other from effective;
  if v_count=0 or not v_known then new.estimated_cost:=null; new.customer_price:=null; end if;
  if v_work_count>0 then
    new.own_labor_ready:=coalesce(v_own,true); new.subcontractor_price_ready:=coalesce(v_sub,true); new.requires_subcontractor:=v_has_sub;
  end if;
  if exists(select 1 from public.action_case_cost_lines where action_case_item_id=new.id and category='material') then new.material_price_ready:=coalesce(v_material,true); end if;
  if exists(select 1 from public.action_case_cost_lines where action_case_item_id=new.id and category in ('waste','transport','other')) then new.waste_solution_ready:=coalesce(v_other,true); end if;
  if old.status in ('scope_needed','pricing_needed','waiting_subcontractor','ready_for_quote') then
    new.status:=case when btrim(coalesce(new.scope,''))='' then 'scope_needed'
      when new.own_labor_ready and new.material_price_ready and new.waste_solution_ready and (not new.requires_subcontractor or new.subcontractor_price_ready)
        and (v_count=0 or (v_known and v_verified)) then 'ready_for_quote'
      when new.requires_subcontractor and not new.subcontractor_price_ready then 'waiting_subcontractor' else 'pricing_needed' end;
  else new.status:=old.status; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.action_case_quote_price_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare q public.action_case_work_quotes%rowtype; d jsonb; v_scope text;
begin
  if tg_op = 'DELETE' then
    if old.covered_by_quote_id is not null and exists(select 1 from public.action_case_items where id=old.action_case_item_id) then
      raise exception 'ACTION_CASE_QUOTE_COVERAGE';
    end if;
    if exists(select 1 from public.action_case_items where id=old.action_case_item_id)
      and exists(select 1 from public.action_case_work_quotes where cost_line_id=old.id and first_attempt_at is not null) then
      raise exception 'ACTION_CASE_QUOTE_SENT_IMMUTABLE';
    end if;
    return old;
  end if;
  if new.covered_by_quote_id is not null and not exists (
    select 1 from public.action_case_work_quotes cq join public.action_case_cost_lines cl on cl.selected_quote_id=cq.id and cl.pricing_method='quotes'
    where cq.id=new.covered_by_quote_id and cq.org_id=new.org_id and cq.action_case_item_id=new.action_case_item_id and new.id=any(cq.covered_line_ids)
  ) then raise exception 'ACTION_CASE_QUOTE_COVERAGE'; end if;
  if tg_op='UPDATE' and old.covered_by_quote_id is not null and new.covered_by_quote_id=old.covered_by_quote_id
    and (new.category,new.description,new.quantity,new.unit,new.unit_cost,new.markup_percent) is distinct from
      (old.category,old.description,old.quantity,old.unit,old.unit_cost,old.markup_percent) then
    raise exception 'ACTION_CASE_QUOTE_COVERAGE';
  end if;
  if tg_op = 'UPDATE' and (new.org_id,new.action_case_id,new.action_case_item_id) is distinct from (old.org_id,old.action_case_id,old.action_case_item_id) then
    raise exception 'ACTION_CASE_COST_LINE_INVALID';
  end if;
  if new.pricing_method = 'quotes' then
    if new.category not in ('own_labor','subcontractor') and not exists(
      select 1 from public.action_case_work_quotes pq where pq.id=new.selected_quote_id
        and pq.cost_line_id=new.id and pq.org_id=new.org_id and pq.package_request_id is not null
    ) then raise exception 'ACTION_CASE_QUOTE_WORK_REQUIRED'; end if;
    if tg_op = 'UPDATE' and old.pricing_method = 'direct' then new.direct_pricing := to_jsonb(old); end if;
    if new.category in ('own_labor','subcontractor') then new.category := 'subcontractor'; end if;
    if new.selected_quote_id is not null then
      select * into q from public.action_case_work_quotes where id=new.selected_quote_id and cost_line_id=new.id and org_id=new.org_id;
      if not found then raise exception 'ACTION_CASE_QUOTE_NOT_FOUND'; end if;
      select coalesce(scope,'') into v_scope from public.action_case_items where id=new.action_case_item_id;
      if q.scope_snapshot <> v_scope or q.description_snapshot <> new.description or not q.checked
        or (q.valid_until is not null and q.valid_until < (now() at time zone 'Europe/Stockholm')::date) then
        new.selected_quote_id := null;
      end if;
    end if;
    new.quantity := 1; new.unit := 'uppdrag'; new.quantity_basis := 'provided'; new.price_source := 'subcontractor';
    new.unit_cost := case when new.selected_quote_id is not null then q.amount end;
    new.is_verified := new.selected_quote_id is not null;
    new.verified_by := case when new.is_verified then new.updated_by end;
    new.verified_at := case when new.is_verified then now() end;
    new.source_checked_at := new.verified_at;
    new.source_url := null;
  elsif tg_op = 'UPDATE' and old.pricing_method = 'quotes' then
    d := coalesce(old.direct_pricing, jsonb_build_object('category','own_labor','unit','tim','quantity_basis','unknown','price_source','manual','is_verified',false));
    new.category := d->>'category'; new.quantity := (d->>'quantity')::numeric; new.unit := d->>'unit';
    new.unit_cost := (d->>'unit_cost')::numeric; new.quantity_basis := d->>'quantity_basis';
    new.markup_percent := coalesce((d->>'markup_percent')::numeric,old.markup_percent);
    new.price_source := d->>'price_source'; new.source_url := d->>'source_url';
    new.is_verified := coalesce((d->>'is_verified')::boolean,false);
    new.verified_by := (d->>'verified_by')::uuid; new.verified_at := (d->>'verified_at')::timestamptz;
    new.source_checked_at := (d->>'source_checked_at')::timestamptz;
    new.selected_quote_id := null;
  end if;
  if tg_op = 'UPDATE' and old.selected_quote_id is not null and old.selected_quote_id is distinct from new.selected_quote_id then
    update public.action_case_cost_lines set covered_by_quote_id=null where covered_by_quote_id=old.selected_quote_id and org_id=new.org_id;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.addon_services_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.assignments_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_operational_task(p_org_id uuid, p_title text, p_due_at timestamp with time zone, p_next_followup_at timestamp with time zone, p_primary_channel text, p_task_kind text, p_evidence_requirement text, p_assignee_profile_id uuid DEFAULT NULL::uuid, p_assignee_contact_id uuid DEFAULT NULL::uuid, p_parent_task_id uuid DEFAULT NULL::uuid, p_expected_parent_version integer DEFAULT NULL::integer, p_description text DEFAULT NULL::text, p_context_label text DEFAULT NULL::text, p_fallback_channel text DEFAULT NULL::text, p_requirements jsonb DEFAULT '[]'::jsonb, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_contact_id uuid DEFAULT NULL::uuid, p_actor_access_link_id uuid DEFAULT NULL::uuid, p_source_ai_suggestion_id uuid DEFAULT NULL::uuid)
 RETURNS operational_tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  caller_profile_id uuid := auth.uid();
  effective_profile_id uuid;
  actor_type_value text;
  actor_name_value text;
  issuer_profile_id_value uuid;
  task_id_value uuid := gen_random_uuid();
  root_task_id_value uuid;
  depth_value integer := 0;
  parent_row public.operational_tasks%rowtype;
  result public.operational_tasks%rowtype;
  configured_max_depth integer;
  configured_max_open_children integer;
  configured_max_active_descendants integer;
  open_children integer;
  active_descendants integer;
  suggestion_row public.task_ai_suggestions%rowtype;
begin
  if nullif(btrim(coalesce(p_title, '')), '') is null
    or p_due_at is null
    or p_next_followup_at is null
    or p_next_followup_at > p_due_at
    or num_nonnulls(p_assignee_profile_id, p_assignee_contact_id) <> 1
  then
    raise exception using errcode = '22023', message = 'TASK_CREATE_INPUT_INVALID';
  end if;

  if p_requirements is null or jsonb_typeof(p_requirements) <> 'array' then
    raise exception using errcode = '22023', message = 'TASK_REQUIREMENTS_INPUT_INVALID';
  end if;

  if jsonb_array_length(p_requirements) > 50
    or exists (
      select 1
      from jsonb_array_elements(p_requirements) as requirement(value)
      where jsonb_typeof(requirement.value) <> 'object'
        or nullif(btrim(coalesce(requirement.value ->> 'requirement_key', '')), '') is null
        or nullif(btrim(coalesce(requirement.value ->> 'label', '')), '') is null
        or coalesce(nullif(requirement.value ->> 'status', ''), 'pending') <> 'pending'
    ) then
    raise exception using errcode = '22023', message = 'TASK_REQUIREMENTS_INPUT_INVALID';
  end if;

  if caller_profile_id is not null then
    if p_actor_contact_id is not null
      or p_actor_access_link_id is not null
      or (p_actor_profile_id is not null and p_actor_profile_id <> caller_profile_id)
    then
      raise exception using errcode = '42501', message = 'TASK_ACTOR_SPOOFING_FORBIDDEN';
    end if;
    effective_profile_id := caller_profile_id;
  elsif auth.role() = 'service_role' then
    if num_nonnulls(p_actor_profile_id, p_actor_contact_id) <> 1 then
      raise exception using errcode = '22023', message = 'TASK_CREATE_ACTOR_REQUIRED';
    end if;
    effective_profile_id := p_actor_profile_id;
  else
    raise exception using errcode = '42501', message = 'TASK_CREATE_FORBIDDEN';
  end if;

  if effective_profile_id is not null then
    if p_actor_access_link_id is not null then
      raise exception using errcode = '42501', message = 'TASK_ACTOR_SPOOFING_FORBIDDEN';
    end if;

    if not exists (
      select 1
      from public.org_members member
      where member.org_id = p_org_id
        and member.profile_id = effective_profile_id
        and member.is_active = true
    ) then
      raise exception using errcode = '42501', message = 'TASK_ACTOR_NOT_IN_ORG';
    end if;

    if caller_profile_id is not null
      and not public.has_operational_task_module_access(p_org_id)
    then
      raise exception using errcode = '42501', message = 'TASK_MODULE_ACCESS_REQUIRED';
    end if;

    actor_type_value := 'profile';
    select coalesce(nullif(btrim(profile.full_name), ''), profile.email, 'Intern anvandare')
    into actor_name_value
    from public.profiles profile
    where profile.id = effective_profile_id;
  else
    actor_type_value := 'contact';
    select contact.name
    into actor_name_value
    from public.organization_contacts contact
    where contact.id = p_actor_contact_id
      and contact.org_id = p_org_id
      and contact.is_active = true;

    if not found or p_actor_access_link_id is null then
      raise exception using errcode = '42501', message = 'TASK_EXTERNAL_ACTOR_FORBIDDEN';
    end if;

    if p_assignee_profile_id is not null then
      raise exception using errcode = '42501', message = 'TASK_EXTERNAL_PROFILE_ASSIGNMENT_FORBIDDEN';
    end if;
  end if;

  select
    settings.max_subtask_depth,
    settings.max_open_children_per_task,
    settings.max_active_descendants
  into
    configured_max_depth,
    configured_max_open_children,
    configured_max_active_descendants
  from public.task_organization_settings settings
  where settings.org_id = p_org_id
  for share;

  configured_max_depth := coalesce(configured_max_depth, 2);
  configured_max_open_children := coalesce(configured_max_open_children, 5);
  configured_max_active_descendants := coalesce(configured_max_active_descendants, 15);

  if p_parent_task_id is null then
    if p_actor_contact_id is not null then
      raise exception using errcode = '42501', message = 'TASK_EXTERNAL_ROOT_FORBIDDEN';
    end if;

    if p_expected_parent_version is not null then
      raise exception using errcode = '22023', message = 'TASK_PARENT_VERSION_NOT_ALLOWED';
    end if;

    if p_source_ai_suggestion_id is not null then
      raise exception using errcode = '22023', message = 'TASK_AI_SUGGESTION_PARENT_REQUIRED';
    end if;

    perform pg_advisory_xact_lock(hashtextextended(p_org_id::text, 2));
    root_task_id_value := task_id_value;
    issuer_profile_id_value := effective_profile_id;
  else
    if p_expected_parent_version is null or p_expected_parent_version <= 0 then
      raise exception using errcode = '22023', message = 'TASK_PARENT_VERSION_REQUIRED';
    end if;

    select task.*
    into parent_row
    from public.operational_tasks task
    where task.id = p_parent_task_id
      and task.org_id = p_org_id
      and task.archived_at is null
    for update;

    if not found then
      raise exception using errcode = 'P0002', message = 'TASK_PARENT_NOT_FOUND';
    end if;

    if parent_row.version <> p_expected_parent_version then
      raise exception using errcode = '40001', message = 'TASK_PARENT_VERSION_CONFLICT';
    end if;

    if parent_row.status in ('approved', 'cancelled') then
      raise exception using errcode = '23514', message = 'TASK_PARENT_CLOSED';
    end if;

    if p_due_at > parent_row.due_at then
      raise exception using errcode = '23514', message = 'TASK_CHILD_AFTER_PARENT_DUE';
    end if;

    if effective_profile_id is not null then
      if parent_row.issuer_profile_id <> effective_profile_id
        and parent_row.assignee_profile_id <> effective_profile_id
        and not exists (
          select 1
          from public.org_members member
          where member.org_id = p_org_id
            and member.profile_id = effective_profile_id
            and member.is_active = true
            and member.role = 'admin'
        )
      then
        raise exception using errcode = '42501', message = 'TASK_SUBTASK_CREATE_FORBIDDEN';
      end if;
      issuer_profile_id_value := effective_profile_id;
    else
      if not public.task_access_link_covers(
        p_actor_access_link_id,
        parent_row.id,
        p_actor_contact_id
      ) or not exists (
        select 1
        from public.task_access_links access_link
        where access_link.id = p_actor_access_link_id
          and access_link.contact_id = p_actor_contact_id
          and access_link.role = 'delegator'
          and access_link.scope = 'branch'
          and access_link.revoked_at is null
          and access_link.expires_at > now()
      ) then
        raise exception using errcode = '42501', message = 'TASK_EXTERNAL_DELEGATION_FORBIDDEN';
      end if;
      issuer_profile_id_value := parent_row.issuer_profile_id;
    end if;

    root_task_id_value := parent_row.root_task_id;
    depth_value := parent_row.depth + 1;

    if p_source_ai_suggestion_id is not null then
      if effective_profile_id is null
        or (
          parent_row.issuer_profile_id <> effective_profile_id
          and not exists (
            select 1
            from public.org_members member
            where member.org_id = p_org_id
              and member.profile_id = effective_profile_id
              and member.is_active = true
              and member.role = 'admin'
          )
        )
      then
        raise exception using errcode = '42501', message = 'TASK_AI_SUGGESTION_ACCEPT_FORBIDDEN';
      end if;

      select suggestion.*
      into suggestion_row
      from public.task_ai_suggestions suggestion
      where suggestion.id = p_source_ai_suggestion_id
        and suggestion.org_id = p_org_id
        and suggestion.task_id = parent_row.id
        and suggestion.root_task_id = parent_row.root_task_id
        and suggestion.suggestion_type = 'create_subtask'
        and suggestion.status = 'pending'
      for update;

      if not found then
        raise exception using errcode = 'P0002', message = 'TASK_AI_SUGGESTION_NOT_PENDING';
      end if;
    end if;

    perform pg_advisory_xact_lock(hashtextextended(root_task_id_value::text, 0));

    if depth_value > configured_max_depth then
      raise exception using errcode = '23514', message = 'TASK_MAX_DEPTH_EXCEEDED';
    end if;

    select count(*) into open_children
    from public.operational_tasks child
    where child.parent_task_id = parent_row.id
      and child.archived_at is null
      and child.status not in ('approved', 'cancelled');

    if open_children >= configured_max_open_children then
      raise exception using errcode = '23514', message = 'TASK_MAX_OPEN_CHILDREN_EXCEEDED';
    end if;

    select count(*) into active_descendants
    from public.operational_tasks descendant
    where descendant.root_task_id = root_task_id_value
      and descendant.id <> descendant.root_task_id
      and descendant.archived_at is null
      and descendant.status not in ('approved', 'cancelled');

    if active_descendants >= configured_max_active_descendants then
      raise exception using errcode = '23514', message = 'TASK_MAX_ACTIVE_DESCENDANTS_EXCEEDED';
    end if;
  end if;

  insert into public.operational_tasks (
    id,
    org_id,
    parent_task_id,
    root_task_id,
    depth,
    issuer_profile_id,
    assignee_profile_id,
    assignee_contact_id,
    title,
    description,
    task_kind,
    status,
    due_at,
    next_followup_at,
    primary_channel,
    fallback_channel,
    context_label,
    evidence_requirement,
    created_source,
    source_ai_suggestion_id,
    created_by_profile_id
  )
  values (
    task_id_value,
    p_org_id,
    p_parent_task_id,
    root_task_id_value,
    depth_value,
    issuer_profile_id_value,
    p_assignee_profile_id,
    p_assignee_contact_id,
    btrim(p_title),
    nullif(btrim(coalesce(p_description, '')), ''),
    p_task_kind,
    'assigned',
    p_due_at,
    p_next_followup_at,
    p_primary_channel,
    nullif(btrim(coalesce(p_fallback_channel, '')), ''),
    nullif(btrim(coalesce(p_context_label, '')), ''),
    p_evidence_requirement,
    case when p_source_ai_suggestion_id is null then 'manual' else 'ai_suggestion' end,
    p_source_ai_suggestion_id,
    effective_profile_id
  )
  returning * into result;

  if p_parent_task_id is not null then
    -- Treat a new child as a parent-tree mutation. This consumes the positive
    -- expected version so duplicate concurrent submissions cannot both pass.
    update public.operational_tasks parent_task
    set last_activity_at = now()
    where parent_task.id = p_parent_task_id
      and parent_task.version = p_expected_parent_version;

    if not found then
      raise exception using errcode = '40001', message = 'TASK_PARENT_VERSION_CONFLICT';
    end if;
  end if;

  insert into public.task_requirements (
    org_id,
    task_id,
    requirement_key,
    label,
    status,
    is_required,
    description,
    sort_order
  )
  select
    p_org_id,
    result.id,
    btrim(requirement.value ->> 'requirement_key'),
    btrim(requirement.value ->> 'label'),
    'pending',
    coalesce((requirement.value ->> 'is_required')::boolean, true),
    nullif(btrim(coalesce(requirement.value ->> 'description', '')), ''),
    coalesce(
      nullif(requirement.value ->> 'sort_order', '')::integer,
      (requirement.ordinality * 100)::integer
    )
  from jsonb_array_elements(p_requirements)
    with ordinality as requirement(value, ordinality);

  if p_source_ai_suggestion_id is not null then
    update public.task_ai_suggestions suggestion
    set
      status = 'accepted',
      reviewed_by_profile_id = effective_profile_id,
      reviewed_at = now(),
      review_note = 'Förslaget användes som underlag för en manuellt skapad underuppgift.',
      accepted_task_id = result.id
    where suggestion.id = p_source_ai_suggestion_id
      and suggestion.status = 'pending';

    if not found then
      raise exception using errcode = '40001', message = 'TASK_AI_SUGGESTION_NOT_PENDING';
    end if;
  end if;

  insert into public.task_events (
    org_id,
    task_id,
    event_type,
    actor_type,
    actor_profile_id,
    actor_contact_id,
    actor_access_link_id,
    actor_name,
    message,
    to_status,
    metadata
  )
  values (
    p_org_id,
    result.id,
    'task_created',
    actor_type_value,
    effective_profile_id,
    p_actor_contact_id,
    p_actor_access_link_id,
    coalesce(actor_name_value, 'Uppdragsgivare'),
    case
      when p_parent_task_id is null then 'Uppgiften skapades och tilldelades.'
      else 'Underuppgiften skapades och tilldelades.'
    end,
    'assigned',
    jsonb_build_object(
      'parentTaskId', p_parent_task_id,
      'rootTaskId', result.root_task_id,
      'depth', result.depth,
      'sourceAiSuggestionId', p_source_ai_suggestion_id
    )
  );

  select task.* into result
  from public.operational_tasks task
  where task.id = task_id_value;

  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_operational_task_deadline_change(p_request_id uuid, p_decision text, p_decision_note text DEFAULT NULL::text, p_expected_task_version integer DEFAULT NULL::integer, p_actor_profile_id uuid DEFAULT NULL::uuid)
 RETURNS task_deadline_change_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  request_row public.task_deadline_change_requests%rowtype;
  task_row public.operational_tasks%rowtype;
  caller_profile_id uuid := auth.uid();
  effective_profile_id uuid;
  actor_name_value text;
  actor_is_admin boolean;
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception using errcode = '22023', message = 'TASK_DEADLINE_DECISION_INVALID';
  end if;

  select request.* into request_row
  from public.task_deadline_change_requests request
  where request.id = p_request_id
  for update;

  if not found or request_row.status <> 'pending' then
    raise exception using errcode = 'P0002', message = 'TASK_DEADLINE_REQUEST_NOT_PENDING';
  end if;

  select task.* into task_row
  from public.operational_tasks task
  where task.id = request_row.task_id
    and task.archived_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'TASK_NOT_FOUND';
  end if;

  if task_row.status in ('approved', 'cancelled') then
    raise exception using errcode = '23514', message = 'TASK_TERMINAL';
  end if;

  effective_profile_id := case
    when caller_profile_id is not null then caller_profile_id
    when auth.role() = 'service_role' then p_actor_profile_id
    else null
  end;

  if effective_profile_id is null
    or (caller_profile_id is not null
      and p_actor_profile_id is not null
      and p_actor_profile_id <> caller_profile_id)
  then
    raise exception using errcode = '42501', message = 'TASK_DEADLINE_DECISION_FORBIDDEN';
  end if;

  if caller_profile_id is not null
    and not public.has_operational_task_module_access(task_row.org_id)
  then
    raise exception using errcode = '42501', message = 'TASK_MODULE_ACCESS_REQUIRED';
  end if;

  actor_is_admin := exists (
    select 1
    from public.org_members member
    where member.org_id = task_row.org_id
      and member.profile_id = effective_profile_id
      and member.is_active = true
      and member.role = 'admin'
  );

  if task_row.issuer_profile_id <> effective_profile_id and not actor_is_admin then
    raise exception using errcode = '42501', message = 'TASK_DEADLINE_DECISION_FORBIDDEN';
  end if;

  if p_expected_task_version is null or p_expected_task_version <= 0 then
    raise exception using errcode = '22023', message = 'TASK_VERSION_REQUIRED';
  end if;

  if task_row.version <> p_expected_task_version then
    raise exception using errcode = '40001', message = 'TASK_VERSION_CONFLICT';
  end if;

  if p_decision = 'approved' and task_row.parent_task_id is not null and exists (
    select 1
    from public.operational_tasks parent
    where parent.id = task_row.parent_task_id
      and request_row.requested_due_at > parent.due_at
  ) then
    raise exception using errcode = '23514', message = 'TASK_CHILD_AFTER_PARENT_DUE';
  end if;

  update public.task_deadline_change_requests request
  set
    status = p_decision,
    decided_by_profile_id = effective_profile_id,
    decided_at = now(),
    decision_note = nullif(btrim(coalesce(p_decision_note, '')), '')
  where request.id = request_row.id
  returning * into request_row;

  if p_decision = 'approved' then
    update public.operational_tasks task
    set
      due_at = request_row.requested_due_at,
      last_activity_at = now()
    where task.id = task_row.id;
  end if;

  select coalesce(nullif(btrim(profile.full_name), ''), profile.email, 'Uppdragsgivare')
  into actor_name_value
  from public.profiles profile
  where profile.id = effective_profile_id;

  insert into public.task_events (
    org_id, task_id, event_type, actor_type, actor_profile_id,
    actor_name, message, metadata
  )
  values (
    task_row.org_id,
    task_row.id,
    case
      when p_decision = 'approved' then 'deadline_change_approved'
      else 'deadline_change_rejected'
    end,
    'profile',
    effective_profile_id,
    coalesce(actor_name_value, 'Uppdragsgivare'),
    nullif(btrim(coalesce(p_decision_note, '')), ''),
    jsonb_build_object(
      'requestedDueAt', request_row.requested_due_at,
      'requestId', request_row.id
    )
  );

  return request_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_operational_task_requirement(p_requirement_id uuid, p_status text, p_evidence_attachment_id uuid, p_reason text, p_expected_task_version integer, p_actor_profile_id uuid DEFAULT NULL::uuid)
 RETURNS task_requirements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  requirement_task_id uuid;
  requirement_row public.task_requirements%rowtype;
  task_row public.operational_tasks%rowtype;
  caller_profile_id uuid := auth.uid();
  effective_profile_id uuid;
  actor_name_value text;
  evidence_id_value uuid;
  expected_attachment_type text;
  evidence_is_mandatory boolean;
begin
  if p_status not in ('pending', 'verified', 'not_required', 'waived')
    or p_expected_task_version is null
    or p_expected_task_version <= 0
  then
    raise exception using errcode = '22023', message = 'TASK_REQUIREMENT_DECISION_INVALID';
  end if;

  select requirement.task_id
  into requirement_task_id
  from public.task_requirements requirement
  where requirement.id = p_requirement_id;

  if not found then
    raise exception using errcode = 'P0002', message = 'TASK_REQUIREMENT_NOT_FOUND';
  end if;

  select task.* into task_row
  from public.operational_tasks task
  where task.id = requirement_task_id
    and task.archived_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'TASK_NOT_FOUND';
  end if;

  select requirement.* into requirement_row
  from public.task_requirements requirement
  where requirement.id = p_requirement_id
    and requirement.task_id = task_row.id
    and requirement.org_id = task_row.org_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'TASK_REQUIREMENT_NOT_FOUND';
  end if;

  if task_row.version <> p_expected_task_version then
    raise exception using errcode = '40001', message = 'TASK_VERSION_CONFLICT';
  end if;

  if task_row.status in ('approved', 'cancelled')
    or (task_row.status = 'ready_for_review' and p_status = 'pending')
  then
    raise exception using errcode = '23514', message = 'TASK_REQUIREMENT_DECISION_LOCKED';
  end if;

  if caller_profile_id is not null then
    if p_actor_profile_id is not null and p_actor_profile_id <> caller_profile_id then
      raise exception using errcode = '42501', message = 'TASK_ACTOR_SPOOFING_FORBIDDEN';
    end if;
    effective_profile_id := caller_profile_id;
  elsif auth.role() = 'service_role' then
    effective_profile_id := p_actor_profile_id;
  else
    raise exception using errcode = '42501', message = 'TASK_REQUIREMENT_DECISION_FORBIDDEN';
  end if;

  if effective_profile_id is null or not exists (
    select 1
    from public.org_members member
    where member.org_id = task_row.org_id
      and member.profile_id = effective_profile_id
      and member.is_active = true
      and (
        task_row.issuer_profile_id = effective_profile_id
        or member.role = 'admin'
      )
  ) then
    raise exception using errcode = '42501', message = 'TASK_REQUIREMENT_DECISION_FORBIDDEN';
  end if;

  if caller_profile_id is not null
    and not public.has_operational_task_module_access(task_row.org_id)
  then
    raise exception using errcode = '42501', message = 'TASK_MODULE_ACCESS_REQUIRED';
  end if;

  if p_status in ('waived', 'not_required')
    and nullif(btrim(coalesce(p_reason, '')), '') is null
  then
    raise exception using errcode = '22023', message = 'TASK_REQUIREMENT_REASON_REQUIRED';
  end if;

  evidence_is_mandatory := requirement_row.requirement_key in (
    'written_quote',
    'written_client_approval',
    'warranty_basis',
    'completion_evidence'
  );

  expected_attachment_type := case
    when requirement_row.requirement_key <> 'completion_evidence' then null
    when task_row.evidence_requirement = 'text' then 'text'
    when task_row.evidence_requirement = 'photo' then 'photo'
    when task_row.evidence_requirement = 'document' then 'document'
    else null
  end;

  if p_status = 'verified' then
    if p_evidence_attachment_id is not null then
      select attachment.id into evidence_id_value
      from public.task_attachments attachment
      where attachment.id = p_evidence_attachment_id
        and attachment.task_id = task_row.id
        and (
          not evidence_is_mandatory
          or (
            requirement_row.requirement_key = 'completion_evidence'
            and attachment.is_completion_evidence = true
            and (
              expected_attachment_type is null
              or attachment.attachment_type = expected_attachment_type
              or (
                expected_attachment_type = 'text'
                and attachment.attachment_type = 'audio'
                and nullif(btrim(coalesce(attachment.transcript_text, '')), '') is not null
              )
            )
          )
          or (
            requirement_row.requirement_key in (
              'written_quote',
              'written_client_approval',
              'warranty_basis'
            )
            and attachment.attachment_type in ('document', 'photo', 'text')
          )
        );
    elsif evidence_is_mandatory then
      select attachment.id into evidence_id_value
      from public.task_attachments attachment
      where attachment.task_id = task_row.id
        and (
          not evidence_is_mandatory
          or (
            requirement_row.requirement_key = 'completion_evidence'
            and attachment.is_completion_evidence = true
            and (
              expected_attachment_type is null
              or attachment.attachment_type = expected_attachment_type
              or (
                expected_attachment_type = 'text'
                and attachment.attachment_type = 'audio'
                and nullif(btrim(coalesce(attachment.transcript_text, '')), '') is not null
              )
            )
          )
          or (
            requirement_row.requirement_key in (
              'written_quote',
              'written_client_approval',
              'warranty_basis'
            )
            and attachment.attachment_type in ('document', 'photo', 'text')
          )
        )
      order by attachment.created_at desc, attachment.id desc
      limit 1;
    end if;

    if p_evidence_attachment_id is not null and evidence_id_value is null then
      raise exception using errcode = '23514', message = 'TASK_REQUIREMENT_EVIDENCE_INVALID';
    end if;

    if evidence_is_mandatory and evidence_id_value is null then
      raise exception using errcode = '23514', message = 'TASK_REQUIREMENT_EVIDENCE_REQUIRED';
    end if;
  elsif p_evidence_attachment_id is not null then
    raise exception using errcode = '22023', message = 'TASK_REQUIREMENT_EVIDENCE_NOT_ALLOWED';
  end if;

  update public.task_requirements requirement
  set
    status = p_status,
    evidence_attachment_id = case
      when p_status = 'verified' then evidence_id_value
      else null
    end,
    verified_by_profile_id = case
      when p_status in ('verified', 'not_required', 'waived') then effective_profile_id
      else null
    end,
    verified_at = case
      when p_status in ('verified', 'not_required', 'waived') then now()
      else null
    end
  where requirement.id = requirement_row.id
  returning * into requirement_row;

  update public.operational_tasks task
  set
    submitted_for_review_at = case
      when task.status = 'ready_for_review' then task.submitted_for_review_at
      else null
    end,
    approved_at = null,
    approved_by_profile_id = null,
    last_activity_at = now()
  where task.id = task_row.id;

  select coalesce(nullif(btrim(profile.full_name), ''), profile.email, 'Uppdragsgivare')
  into actor_name_value
  from public.profiles profile
  where profile.id = effective_profile_id;

  insert into public.task_events (
    org_id,
    task_id,
    event_type,
    actor_type,
    actor_profile_id,
    actor_name,
    message,
    metadata
  )
  values (
    task_row.org_id,
    task_row.id,
    'requirement_updated',
    'profile',
    effective_profile_id,
    coalesce(actor_name_value, 'Uppdragsgivare'),
    coalesce(
      nullif(btrim(coalesce(p_reason, '')), ''),
      requirement_row.label || ': ' || p_status
    ),
    jsonb_build_object(
      'requirementId', requirement_row.id,
      'requirementKey', requirement_row.requirement_key,
      'status', p_status,
      'evidenceAttachmentId', evidence_id_value,
      'taskMutationApplied', true
    )
  );

  return requirement_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.eb_follow_up_guard_order()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if (to_jsonb(new) - array['billing_status','withdrawal_requested_at'])
    is distinct from (to_jsonb(old) - array['billing_status','withdrawal_requested_at']) then
    raise exception 'EB_FOLLOW_UP_ORDER_IMMUTABLE';
  end if;
  if old.withdrawal_requested_at is not null and new.withdrawal_requested_at is distinct from old.withdrawal_requested_at then
    raise exception 'EB_FOLLOW_UP_WITHDRAWAL_IMMUTABLE';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.eb_guard_paid_remediation_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    if old.follow_up_order_id is not null then raise exception 'EB_FOLLOW_UP_TASK_IMMUTABLE'; end if;
    return old;
  end if;
  if (old.follow_up_order_id is not null or new.follow_up_order_id is not null)
    and (
      (old.id, old.org_id, old.eb_project_id, old.inspection_id, old.follow_up_order_id, old.original_note_id)
        is distinct from
      (new.id, new.org_id, new.eb_project_id, new.inspection_id, new.follow_up_order_id, new.original_note_id)
      or old.note_snapshot is distinct from new.note_snapshot
      or old.original_images is distinct from new.original_images
    ) then raise exception 'EB_FOLLOW_UP_TASK_IMMUTABLE';
  end if;
  -- eb_note_id may become null on deletion of a live note. original_note_id,
  -- the purchased text and original images remain unchanged.
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.eb_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_action_case_grouped_price_selection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r public.action_case_quote_requests%rowtype; source jsonb;
begin
  select req.* into r from public.action_case_work_quotes q join public.action_case_quote_requests req on req.id=q.request_id
    where q.id=new.selected_quote_id;
  if found then
    if r.response_mode<>'itemized' or r.sent_at is null then raise exception 'ACTION_CASE_REQUEST_PACKAGE_PRICE'; end if;
    select s into source from jsonb_array_elements(r.lines) s where (s->>'costLineId')::uuid=new.id;
    if source is null or not public.action_case_request_source_matches(new.org_id,new.action_case_id,source,true)
      or (to_jsonb(new)->>'work_part_id') is distinct from (source->>'workPartId') then raise exception 'ACTION_CASE_QUOTE_STALE'; end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_action_case_grouped_quote()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.action_case_quote_requests%rowtype;
begin
  if tg_op='DELETE' then
    if old.request_id is not null and exists(select 1 from public.action_case_items where id=old.action_case_item_id) then raise exception 'ACTION_CASE_QUOTE_SENT_IMMUTABLE'; end if;
    return old;
  end if;
  if tg_op='UPDATE' and new.request_id is distinct from old.request_id then raise exception 'ACTION_CASE_REQUEST_INVALID'; end if;
  if new.request_id is null then return new; end if;
  select * into r from public.action_case_quote_requests where id=new.request_id and org_id=new.org_id and action_case_id=new.action_case_id;
  if not found or r.first_attempt_at is null or not exists(select 1 from jsonb_array_elements(r.lines) s where (s->>'costLineId')::uuid=new.cost_line_id and (s->>'itemId')::uuid=new.action_case_item_id
    and s->>'scope'=new.scope_snapshot and s->>'description'=new.description_snapshot) then raise exception 'ACTION_CASE_REQUEST_INVALID'; end if;
  if (new.supplier_name,new.supplier_email,new.request_subject,new.request_body,new.request_attachment_ids) is distinct from
    (r.supplier_name,r.supplier_email,r.subject,r.body,r.attachment_ids) then raise exception 'ACTION_CASE_QUOTE_SENT_IMMUTABLE'; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_customer_offer_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if (new.id,new.org_id,new.action_case_id,new.participant_id,new.version,new.draft_revision,new.snapshot,new.files,new.published_at,new.published_by,new.email_payload)
    is distinct from (old.id,old.org_id,old.action_case_id,old.participant_id,old.version,old.draft_revision,old.snapshot,old.files,old.published_at,old.published_by,old.email_payload)
    or (old.status <> 'published' and (new.status,new.accepted_at,new.accepted_by,new.accepted_option_ids,new.accepted_total_ore)
      is distinct from (old.status,old.accepted_at,old.accepted_by,old.accepted_option_ids,old.accepted_total_ore)) then
    raise exception 'CUSTOMER_OFFER_IMMUTABLE';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_locked_inspection_child_write()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'INSERT' then
    perform public.raise_if_inspection_locked(new.inspection_id, tg_table_name);
    return new;
  end if;

  if tg_op = 'UPDATE' then
    perform public.raise_if_inspection_locked(old.inspection_id, tg_table_name);
    perform public.raise_if_inspection_locked(new.inspection_id, tg_table_name);
    return new;
  end if;

  if tg_op = 'DELETE' then
    perform public.raise_if_inspection_locked(old.inspection_id, tg_table_name);
    return old;
  end if;

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_locked_inspections_write()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    if old.locked_at is not null then
      raise exception using
        errcode = '55000',
        message = 'Låst besiktning kan inte raderas.',
        detail = format('inspection_id=%s', old.id::text);
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' then
    if old.locked_at is not null then
      if (to_jsonb(new) - array['locked_at', 'locked_by', 'updated_at', 'inspection_family', 'inspection_variant'])
        <> (to_jsonb(old) - array['locked_at', 'locked_by', 'updated_at', 'inspection_family', 'inspection_variant']) then
        raise exception using
          errcode = '55000',
          message = 'Låst besiktning kan inte ändras.',
          detail = format('inspection_id=%s', old.id::text);
      end if;
    end if;
    return new;
  end if;

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_project_manager()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if (tg_op='INSERT' and new.manager_profile_id is not null) or (tg_op='UPDATE' and new.manager_profile_id is distinct from old.manager_profile_id) then
    if auth.role() is distinct from 'service_role' then raise exception 'PROJECT_MANAGER_FORBIDDEN'; end if;
    if new.manager_profile_id is not null and not exists(select 1 from public.org_members m where m.org_id=new.org_id and m.profile_id=new.manager_profile_id and m.is_active) then raise exception 'PROJECT_MANAGER_INVALID'; end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_structured_contract_property()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare p jsonb; linked uuid;
begin
  if tg_table_name = 'action_case_customer_offers' then
    perform public.assert_contract_property(new.snapshot, true);
    return new;
  end if;
  if tg_op = 'UPDATE' and old.body->'contractDetails' ? 'property'
    and not (new.body->'contractDetails' ? 'property') then raise exception 'PROPERTY_INVALID'; end if;
  perform public.assert_contract_property(new.body, false);
  p := new.body->'contractDetails'->'property';
  if p is not null then
    if p ? 'sourcePropertyId' then
      select c.property_id into linked from public.action_cases c
        join public.properties r on r.id = c.property_id
        where c.id = new.action_case_id and c.org_id = new.org_id
          and public.property_identity_key(r.municipality, r.cadastral_id) = public.property_identity_key(p->>'municipality', p->>'cadastralDesignation');
      if linked is distinct from (p->>'sourcePropertyId')::uuid then raise exception 'PROPERTY_STALE'; end if;
    else
      -- Changing identity removes only this project's link, never the shared property or its reports.
      update public.action_cases set property_id = null, property_link_request_id = null, property_link_fingerprint = null
        where id = new.action_case_id and org_id = new.org_id and property_id is not null;
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_task_recipient_access_link_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  access_link_id_value uuid;
  provided_contact_id uuid;
  initial_link_contact_id uuid;
  initial_portal_grant_id uuid;
  task_row public.operational_tasks%rowtype;
  contact_row public.organization_contacts%rowtype;
  identity_row public.task_recipient_identities%rowtype;
  grant_row public.task_recipient_portal_grants%rowtype;
  link_row public.task_access_links%rowtype;
begin
  if tg_table_name = 'task_events' then
    access_link_id_value := new.actor_access_link_id;
    provided_contact_id := new.actor_contact_id;
  elsif tg_table_name = 'task_attachments' then
    access_link_id_value := new.uploaded_by_access_link_id;
    provided_contact_id := new.uploaded_by_contact_id;
  else
    raise exception using
      errcode = '0A000',
      message = 'TASK_ACCESS_LINK_WRITE_TABLE_UNSUPPORTED';
  end if;

  -- Profile/system writes and records without an external actor retain their
  -- established semantics. Any access-link-based write is checked below;
  -- task_access_link_covers preserves legacy task/branch behavior.
  if access_link_id_value is null then
    return new;
  end if;

  if provided_contact_id is null then
    raise exception using
      errcode = '23514',
      message = 'TASK_ACCESS_LINK_WRITE_CONTACT_REQUIRED';
  end if;

  -- Unlocked discovery only determines which canonical rows to lock. Every
  -- value is read and validated again after the locks have been acquired.
  select
    access_link.contact_id,
    access_link.portal_grant_id
  into initial_link_contact_id, initial_portal_grant_id
  from public.task_access_links access_link
  where access_link.id = access_link_id_value;

  if not found or initial_link_contact_id <> provided_contact_id then
    raise exception using
      errcode = '42501',
      message = 'TASK_ACCESS_LINK_WRITE_FORBIDDEN';
  end if;

  select task.*
  into task_row
  from public.operational_tasks task
  where task.id = new.task_id
  for update;

  if not found or task_row.org_id <> new.org_id then
    raise exception using
      errcode = '42501',
      message = 'TASK_ACCESS_LINK_WRITE_FORBIDDEN';
  end if;

  select contact.*
  into contact_row
  from public.organization_contacts contact
  where contact.id = initial_link_contact_id
  for share;

  if not found
    or contact_row.org_id <> new.org_id
    or contact_row.is_active = false
  then
    raise exception using
      errcode = '42501',
      message = 'TASK_ACCESS_LINK_WRITE_FORBIDDEN';
  end if;

  if initial_portal_grant_id is not null then
    if contact_row.recipient_identity_id is null then
      raise exception using
        errcode = '42501',
        message = 'TASK_PORTAL_WRITE_FORBIDDEN';
    end if;

    select identity.*
    into identity_row
    from public.task_recipient_identities identity
    where identity.id = contact_row.recipient_identity_id
    for share;

    if not found or identity_row.status <> 'active' then
      raise exception using
        errcode = '42501',
        message = 'TASK_PORTAL_WRITE_FORBIDDEN';
    end if;

    select portal_grant.*
    into grant_row
    from public.task_recipient_portal_grants portal_grant
    where portal_grant.id = initial_portal_grant_id
    for share;

    if not found
      or grant_row.revoked_at is not null
      or grant_row.recipient_identity_id <> identity_row.id
      or grant_row.org_id <> new.org_id
      or grant_row.contact_id <> contact_row.id
      or grant_row.task_id <> task_row.id
      or grant_row.grant_role <> 'assignee'
    then
      raise exception using
        errcode = '42501',
        message = 'TASK_PORTAL_WRITE_FORBIDDEN';
    end if;
  end if;

  select access_link.*
  into link_row
  from public.task_access_links access_link
  where access_link.id = access_link_id_value
  for share;

  if not found
    or link_row.contact_id <> contact_row.id
    or link_row.org_id <> new.org_id
    or link_row.revoked_at is not null
    or link_row.expires_at <= now()
    or link_row.portal_grant_id is distinct from initial_portal_grant_id
    or not public.task_access_link_covers(
      link_row.id,
      task_row.id,
      contact_row.id
    )
  then
    raise exception using
      errcode = '42501',
      message = 'TASK_ACCESS_LINK_WRITE_FORBIDDEN';
  end if;

  if initial_portal_grant_id is not null and (
    task_row.archived_at is not null
    or task_row.status in ('approved', 'cancelled')
    or task_row.assignee_contact_id is distinct from contact_row.id
    or link_row.task_id <> task_row.id
    or link_row.root_task_id <> task_row.root_task_id
    or link_row.role <> 'assignee'
    or link_row.scope <> 'task'
  ) then
    raise exception using
      errcode = '42501',
      message = 'TASK_PORTAL_WRITE_FORBIDDEN';
  end if;

  return new;
end;
$function$

