CREATE OR REPLACE FUNCTION public.invalidate_action_case_file_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_removed boolean;
begin
  if tg_op = 'INSERT' then
    update public.action_case_items set updated_at = clock_timestamp()
      where id = new.action_case_item_id and org_id = new.org_id
        and action_case_id = new.action_case_id and scope_attachment_ids is null;
    return new;
  end if;
  v_removed := tg_op = 'DELETE';
  if tg_op = 'UPDATE' then
    if new is not distinct from old then return new; end if;
    v_removed := new.org_id <> old.org_id or new.action_case_id <> old.action_case_id or new.id <> old.id;
  end if;
  -- Bumping the existing item version invalidates generated costing proposals.
  update public.action_case_items i set
    scope_attachment_ids = case when v_removed and scope_attachment_ids is not null then array(
      select selected.id from unnest(scope_attachment_ids) with ordinality selected(id, position)
      join public.action_case_attachments a on a.id = selected.id and a.org_id = i.org_id and a.action_case_id = i.action_case_id
      order by selected.position
    ) else scope_attachment_ids end,
    updated_at = clock_timestamp()
    where org_id = old.org_id and action_case_id = old.action_case_id
      and (old.id = any(scope_attachment_ids) or (scope_attachment_ids is null and id = old.action_case_item_id));
  if tg_op = 'UPDATE' then
    update public.action_case_items set updated_at = clock_timestamp()
      where id = new.action_case_item_id and org_id = new.org_id
        and action_case_id = new.action_case_id and scope_attachment_ids is null;
    return new;
  end if;
  return old;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_tu_analysis_stale_after_source_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_org_id uuid;
  v_inspection_id uuid;
  v_run_id uuid;
begin
  v_org_id := case when tg_op = 'DELETE' then old.org_id else new.org_id end;
  v_inspection_id := case when tg_op = 'DELETE' then old.inspection_id else new.inspection_id end;

  if tg_table_name = 'technical_investigation_images' then
    if tg_op = 'INSERT' and new.section_key = 'cover' then
      return new;
    end if;

    if tg_op = 'DELETE' and old.section_key = 'cover' then
      return old;
    end if;

    if tg_op = 'UPDATE' then
      if old.section_key = 'cover' and new.section_key = 'cover' then
        return new;
      end if;

      if old.section_key <> 'cover'
        and new.section_key <> 'cover'
        and new.file_path is not distinct from old.file_path
        and new.storage_bucket is not distinct from old.storage_bucket
        and new.caption is not distinct from old.caption
      then
        return new;
      end if;
    end if;
  end if;

  if tg_table_name = 'technical_investigation_details' and tg_op = 'UPDATE' then
    -- title, project_type and report_draft belong to the reviewed report. They
    -- may be edited without making the technical field analysis obsolete.
    if new.scope_description is not distinct from old.scope_description
      and new.background is not distinct from old.background
      and new.basis is not distinct from old.basis
      and new.accessibility is not distinct from old.accessibility
      and new.property_object_type is not distinct from old.property_object_type
      and new.brf_name is not distinct from old.brf_name
      and new.apartment_number is not distinct from old.apartment_number
      and new.apartment_holder_name is not distinct from old.apartment_holder_name
    then
      return new;
    end if;
  end if;

  select current_analysis_run_id
  into v_run_id
  from public.tu_analysis_workflows
  where org_id = v_org_id
    and inspection_id = v_inspection_id
    and status <> 'in_progress';

  if not found then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if v_run_id is not null then
    update public.tu_ai_runs
    set
      status = 'cancelled',
      error_message = 'Källunderlaget ändrades efter att analysen startades.',
      progress_stage = 'cancelled',
      progress_message = 'Analysen avbröts eftersom underlaget ändrades.',
      heartbeat_at = now(),
      completed_at = now()
    where id = v_run_id
      and status in ('queued', 'processing');
  end if;

  update public.tu_analysis_workflows
  set
    status = 'in_progress',
    analysis_approved_at = null,
    analysis_approved_by = null,
    analysis_stale_at = now()
  where org_id = v_org_id
    and inspection_id = v_inspection_id;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_tu_control_plan_stale_after_document_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_org_id uuid;
  v_inspection_id uuid;
  v_affects_analysis boolean;
  v_plan_run_id uuid;
  v_analysis_run_id uuid;
begin
  v_org_id := case when tg_op = 'DELETE' then old.org_id else new.org_id end;
  v_inspection_id := case when tg_op = 'DELETE' then old.inspection_id else new.inspection_id end;
  v_affects_analysis := case
    when tg_op = 'INSERT' then new.use_in_analysis
    when tg_op = 'DELETE' then old.use_in_analysis
    else old.use_in_analysis or new.use_in_analysis
  end;

  if not v_affects_analysis then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if tg_op = 'UPDATE'
    and new.use_in_analysis is not distinct from old.use_in_analysis
    and new.analysis_source_role is not distinct from old.analysis_source_role
    and new.source_party is not distinct from old.source_party
    and new.document_date is not distinct from old.document_date
    and new.file_path is not distinct from old.file_path
    and new.title is not distinct from old.title
  then
    return new;
  end if;

  select current_plan_run_id into v_plan_run_id
  from public.tu_post_damage_cases
  where org_id = v_org_id and inspection_id = v_inspection_id;

  if v_plan_run_id is not null then
    update public.tu_ai_runs
    set status = 'cancelled',
        error_message = 'Källdokumenten ändrades efter att kontrollplanen startades.',
        progress_stage = 'cancelled',
        progress_message = 'Kontrollplanen blev inaktuell när underlaget ändrades.',
        heartbeat_at = now(),
        completed_at = now()
    where id = v_plan_run_id and status in ('queued', 'processing');
  end if;

  update public.tu_post_damage_cases
  set status = 'draft',
      plan_stale_at = case when current_plan_run_id is null then plan_stale_at else now() end,
      plan_approved_at = null,
      plan_approved_by = null
  where org_id = v_org_id and inspection_id = v_inspection_id;

  select current_analysis_run_id into v_analysis_run_id
  from public.tu_analysis_workflows
  where org_id = v_org_id
    and inspection_id = v_inspection_id
    and status <> 'in_progress';

  if found then
    if v_analysis_run_id is not null then
      update public.tu_ai_runs
      set status = 'cancelled',
          error_message = 'Källunderlaget ändrades efter att analysen startades.',
          progress_stage = 'cancelled',
          progress_message = 'Analysen avbröts eftersom underlaget ändrades.',
          heartbeat_at = now(),
          completed_at = now()
      where id = v_analysis_run_id and status in ('queued', 'processing');
    end if;

    update public.tu_analysis_workflows
    set status = 'in_progress',
        analysis_approved_at = null,
        analysis_approved_by = null,
        analysis_stale_at = now()
    where org_id = v_org_id and inspection_id = v_inspection_id;
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

