CREATE OR REPLACE FUNCTION public.ob_building_guard_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r jsonb; b jsonb; v_inspection uuid; v_part uuid; v_parent uuid; v_levels jsonb; v_floor text; v_key text;
begin
  r := case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  b := case when tg_op='UPDATE' then to_jsonb(old) else r end;
  v_inspection := (r->>'inspection_id')::uuid;
  if not exists(select 1 from public.ob_inspection_structure where inspection_id=v_inspection)
    and not exists(select 1 from public.ob_inspection_structure where inspection_id=(b->>'inspection_id')::uuid) then
    if r->>'building_part_id' is not null then raise exception 'OB_BUILDING_NOT_ACTIVE'; end if;
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if coalesce(current_setting('ob.building_command',true),'') <> v_inspection::text
    or coalesce(nullif(current_setting('request.jwt.claim.role',true),''),
      nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','') <> 'service_role' then raise exception 'OB_BUILDING_CLIENT_REQUIRED'; end if;
  perform public.raise_if_inspection_locked(v_inspection,tg_table_name);
  if coalesce((public.ob_assignment_workflow_state(v_inspection)->>'paused')::boolean,false) then raise exception 'OB_ROUND_PAUSED'; end if;
  if (b->>'inspection_id')::uuid <> v_inspection then raise exception 'OB_ROUND_FOREIGN'; end if;
  if tg_op='DELETE' then
    update public.ob_inspection_structure set revision=revision+1 where inspection_id=v_inspection;
    return old;
  end if;
  v_part := (r->>'building_part_id')::uuid;
  if v_part is null and tg_table_name <> 'inspection_images' then raise exception 'OB_BUILDING_REQUIRED'; end if;
  if v_part is not null and not exists(select 1 from public.ob_inspection_buildings where id=v_part and inspection_id=v_inspection) then raise exception 'OB_ROUND_FOREIGN'; end if;
  foreach v_key in array array['interior_room_id','exterior_observation_id','control_item_id'] loop
    if r->>v_key is not null then
      if v_key='interior_room_id' then select building_part_id into v_parent from public.inspection_interior_rooms where id=(r->>v_key)::uuid and inspection_id=v_inspection;
      elsif v_key='exterior_observation_id' then select building_part_id into v_parent from public.inspection_exterior_observations where id=(r->>v_key)::uuid and inspection_id=v_inspection;
      else select building_part_id into v_parent from public.inspection_control_items where id=(r->>v_key)::uuid and inspection_id=v_inspection; end if;
      if not found or v_parent is distinct from v_part then raise exception 'OB_ROUND_FOREIGN'; end if;
    end if;
  end loop;
  if r->>'interior_room_id' is not null and r->>'exterior_observation_id' is not null then raise exception 'OB_ROUND_FOREIGN'; end if;
  if tg_table_name='inspection_images' then
    if tg_op='UPDATE' and current_setting('ob.building_activation',true) is distinct from 'true' and
      (r->>'origin_building_part_id' is distinct from b->>'origin_building_part_id' or r->>'file_path' is distinct from b->>'file_path') then raise exception 'OB_ROUND_STALE'; end if;
    if r->>'origin_building_part_id' is not null and not exists(select 1 from public.ob_inspection_buildings
      where id=(r->>'origin_building_part_id')::uuid and inspection_id=v_inspection) then raise exception 'OB_ROUND_FOREIGN'; end if;
  end if;
  v_floor := case when tg_table_name='inspection_interior_rooms' then r->>'floor_label'
    when tg_table_name='inspection_overview_selections' then r->>'floor_key' end;
  select levels into v_levels from public.ob_building_floor_models where building_part_id=v_part;
  if v_floor is not null and v_floor not in ('ovrigt',U&'\00F6vrigt') and v_levels is not null
    and not exists(select 1 from jsonb_array_elements(v_levels) x where 'plan' || (x->>'level')=v_floor) then raise exception 'OB_FLOOR_UNKNOWN'; end if;
  new.ob_revision := case when tg_op='UPDATE' then old.ob_revision+1 else 1 end;
  update public.ob_inspection_structure set revision=revision+1 where inspection_id=v_inspection;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.ob_building_guard_shared()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_id uuid; r jsonb; b jsonb; k text;
begin
  r := case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  b := case when tg_op='UPDATE' then to_jsonb(old) else '{}' end;
  v_id := (case when tg_table_name='inspections' then r->>'id' else r->>'inspection_id' end)::uuid;
  if exists(select 1 from public.ob_inspection_structure where inspection_id=v_id) then
    if tg_table_name='inspection_conditions' then
      foreach k in array array['furnishing_level','building_type','building_year','building_form','building_subtype',
        'foundation','frame','joists','facade','windows','roof','heating','ventilation','water','sewer'] loop
        if tg_op<>'UPDATE' or r->k is distinct from b->k then raise exception 'OB_BUILDING_CLIENT_REQUIRED'; end if;
      end loop;
    elsif tg_table_name='inspection_floor_models' or tg_table_name in ('inspection_control_answers','inspection_control_point_answers','inspection_exterior_selections','inspection_interior_observations') then
      raise exception 'OB_BUILDING_CLIENT_REQUIRED';
    elsif tg_table_name='inspections' and r->>'cover_path' is distinct from b->>'cover_path' then
      raise exception 'OB_BUILDING_CLIENT_REQUIRED';
    end if;
    perform 1 from public.inspections where id=v_id for update;
    update public.ob_inspection_structure set revision=revision+1 where inspection_id=v_id;
  end if;
  if tg_op='DELETE' then return old; else return new; end if;
end $function$

CREATE OR REPLACE FUNCTION public.ob_ensure_basement_room()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_room uuid; i public.inspections;
begin
  if to_jsonb(new)->>'building_part_id' is not null then
    if current_setting('ob.building_activation',true)='true' then return new; end if;
    perform public.ob_building_basement(new.inspection_id,(to_jsonb(new)->>'building_part_id')::uuid);
    return new;
  end if;
  if not exists(select 1 from public.inspection_floor_models where inspection_id = new.inspection_id)
    or exists(select 1 from public.ob_auto_rooms where inspection_id = new.inspection_id and rule_key = 'basement') then return new; end if;
  select * into i from public.inspections where id = new.inspection_id for update;
  if i.locked_at is not null or lower(coalesce(i.status,'')) in ('completed','klar','done')
    or coalesce((public.ob_assignment_workflow_state(i.id)->>'paused')::boolean,false) then return new; end if;
  if not exists (
    select 1 from public.inspection_overview_selections s
    join public.settings_overview_items it on it.id = s.overview_item_id and it.key = 'building_type'
    join public.settings_overview_groups g on g.overview_item_id = it.id and g.key in ('basement','kallare',U&'k\00E4llare')
    join public.settings_overview_options o on o.group_id = g.id and o.value = s.values->>g.key
    where s.inspection_id = i.id and lower(btrim(o.system_value)) in ('ja','yes','true')
      and s.set_index = (select min(s2.set_index) from public.inspection_overview_selections s2
        where s2.inspection_id = i.id and s2.overview_item_id = it.id)
  ) then return new; end if;
  -- The marker survives a user's move, rename or deletion of the auto-created room.
  insert into public.ob_auto_rooms(inspection_id,rule_key) values(i.id,'basement') on conflict do nothing;
  if not found then return new; end if;
  select id into v_room from public.inspection_interior_rooms where inspection_id = i.id
    and floor_label = 'ovrigt' and (room_type_key = 'kallare' or lower(btrim(room_label)) = U&'k\00E4llare')
    order by order_index, id limit 1;
  if v_room is null then
    insert into public.inspection_interior_rooms(inspection_id,floor_label,room_type_key,room_label,order_index,values)
    select i.id,'ovrigt','kallare',U&'K\00E4llare',coalesce(max(order_index),0) + 10,'{}'::jsonb
    from public.inspection_interior_rooms where inspection_id = i.id and floor_label = 'ovrigt'
    returning id into v_room;
  end if;
  update public.ob_auto_rooms set room_id = v_room where inspection_id = i.id and rule_key = 'basement';
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.ob_guard_floor_key()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_key text; v_levels jsonb;
begin
  if to_jsonb(new)->>'building_part_id' is not null then return new; end if;
  v_key := to_jsonb(new)->>tg_argv[0];
  if tg_op = 'UPDATE' and v_key is not distinct from (to_jsonb(old)->>tg_argv[0])
    and old.inspection_id = new.inspection_id then return new; end if;
  perform 1 from public.inspections where id = new.inspection_id for update;
  select levels into v_levels from public.inspection_floor_models where inspection_id = new.inspection_id;
  if v_levels is null or v_key is null or v_key in ('ovrigt', U&'\00F6vrigt') then return new; end if;
  if not exists(select 1 from jsonb_array_elements(v_levels) r where 'plan' || (r->>'level') = v_key) then
    raise exception 'OB_FLOOR_UNKNOWN';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.ob_organization_row_access(p_inspection uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.inspections; bound_org uuid;
begin
  select * into i from public.inspections where id=p_inspection;
  if not found then return false; end if;
  select org_id into bound_org from public.ob_organization_bindings where inspection_id=p_inspection;
  if bound_org is null and not (to_jsonb(i)->>'inspection_family'='OB' or
    (to_jsonb(i)->>'inspection_family' is null and to_jsonb(i)->>'type' in ('OB','STATUS'))) then return true; end if;
  return bound_org is not null and exists(select 1 from public.properties p where p.id=i.property_id and p.owner=auth.uid())
    and public.ob_actor_has_organization_access(bound_org,auth.uid());
end $function$

CREATE OR REPLACE FUNCTION public.ob_organization_storage_access(p_bucket text, p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare id_text text;
begin
  if p_bucket<>'inspection-images' then return true; end if;
  id_text:=split_part(p_name,'/',1);
  if id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return false; end if;
  return public.ob_organization_row_access(id_text::uuid);
end $function$

CREATE OR REPLACE FUNCTION public.ob_overview_item_flags(p_org_id uuid, p_assignment_id uuid, p_workflow_inspection_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  a public.assignments;
  current_assignment_id uuid;
  state jsonb;
begin
  if auth.uid() is null or not public.ob_actor_has_organization_access(p_org_id,auth.uid()) then
    raise exception 'OB_OVERVIEW_ORG_FORBIDDEN' using errcode = '42501';
  end if;

  if p_assignment_id is not null then
    select * into a from public.assignments
      where id = p_assignment_id and org_id = p_org_id and assignment_type in ('OB', 'STATUS') and public.ob_assignment_visibility_access(org_id,responsible_profile_id,inspection_id,false);
    if not found then
      raise exception 'OB_OVERVIEW_ASSIGNMENT_FORBIDDEN' using errcode = '42501';
    end if;
  end if;

  if p_workflow_inspection_id is not null then
    select w.current_assignment_id into current_assignment_id
      from public.ob_assignment_workflows w
      join public.assignments current_a on current_a.id = w.current_assignment_id
      where w.inspection_id = p_workflow_inspection_id and w.org_id = p_org_id
        and current_a.org_id = p_org_id and current_a.assignment_type = 'OB' and public.ob_assignment_visibility_access(current_a.org_id,current_a.responsible_profile_id,current_a.inspection_id,false) and public.ob_inspection_visibility_access(w.inspection_id,p_org_id,auth.uid(),false);
    if not found then
      raise exception 'OB_OVERVIEW_WORKFLOW_FORBIDDEN' using errcode = '42501';
    end if;
    if p_assignment_id is not null and p_assignment_id <> current_assignment_id then
      raise exception 'OB_OVERVIEW_WORKFLOW_CHANGED';
    end if;
    state := public.ob_assignment_workflow_state(p_workflow_inspection_id);
    if state is null or (state->>'assignmentId')::uuid is distinct from current_assignment_id then
      raise exception 'OB_OVERVIEW_WORKFLOW_CHANGED';
    end if;
  end if;

  return jsonb_build_object(
    'activeLink', exists (select 1 from public.assignment_links l
      where l.assignment_id = a.id and l.org_id = p_org_id and l.used_at is null
        and l.revoked_at is null and l.expires_at > now()),
    'approvalVerified', a.accepted_at is not null and exists (
      select 1 from public.assignment_acceptances accepted
      where accepted.assignment_id = a.id and accepted.org_id = p_org_id
        and accepted.accepted_at = a.accepted_at),
    'linkIssue', exists (select 1 from public.assignment_link_incidents incident
      where incident.assignment_id = a.id and incident.org_id = p_org_id and incident.resolved_at is null),
    'assignmentId', case when state is null then to_jsonb(a.id) else state->'assignmentId' end,
    'needsReview', coalesce((state->>'needsReview')::boolean, false),
    'paused', coalesce((state->>'paused')::boolean, false),
    'reason', state->'reason'
  );
end;
$function$

