CREATE OR REPLACE FUNCTION public.raise_if_inspection_locked(p_inspection_id uuid, p_table_name text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  v_locked_at timestamptz;
begin
  if p_inspection_id is null then
    return;
  end if;

  select i.locked_at
  into v_locked_at
  from public.inspections i
  where i.id = p_inspection_id;

  if v_locked_at is not null then
    raise exception using
      errcode = '55000',
      message = 'Besiktningen är låst och kan inte ändras.',
      detail = format('table=%s inspection_id=%s', coalesce(p_table_name, '?'), p_inspection_id::text);
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_operational_task_transcription_attempt(p_org_id uuid, p_task_id uuid, p_actor_profile_id uuid, p_actor_contact_id uuid, p_actor_access_link_id uuid, p_byte_size bigint)
 RETURNS task_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  task_row public.operational_tasks%rowtype;
  event_row public.task_events%rowtype;
  actor_type_value text;
  actor_name_value text;
  bucket_key text;
  max_attempts integer;
  current_attempts bigint;
  access_role text;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'TASK_TRANSCRIPTION_ATTEMPT_FORBIDDEN';
  end if;

  if p_org_id is null
    or p_task_id is null
    or p_byte_size is null
    or p_byte_size < 0
    or not (
      (
        p_actor_profile_id is not null
        and p_actor_contact_id is null
        and p_actor_access_link_id is null
      )
      or
      (
        p_actor_profile_id is null
        and p_actor_contact_id is not null
        and p_actor_access_link_id is not null
      )
    )
  then
    raise exception using errcode = '22023', message = 'TASK_TRANSCRIPTION_ATTEMPT_INPUT_INVALID';
  end if;

  select task.*
  into task_row
  from public.operational_tasks task
  where task.id = p_task_id
    and task.org_id = p_org_id
    and task.archived_at is null;

  if not found then
    raise exception using errcode = 'P0002', message = 'TASK_NOT_FOUND';
  end if;

  if task_row.status in ('ready_for_review', 'approved', 'cancelled') then
    raise exception using errcode = '23514', message = 'TASK_ATTACHMENT_LOCKED';
  end if;

  if p_actor_profile_id is not null then
    select coalesce(nullif(btrim(profile.full_name), ''), profile.email, 'Intern anvandare')
    into actor_name_value
    from public.org_members member
    join public.profiles profile on profile.id = member.profile_id
    where member.org_id = p_org_id
      and member.profile_id = p_actor_profile_id
      and member.is_active = true
      and (
        member.role = 'admin'
        or task_row.issuer_profile_id = p_actor_profile_id
        or task_row.assignee_profile_id = p_actor_profile_id
      );

    if not found then
      raise exception using errcode = '42501', message = 'TASK_TRANSCRIPTION_ACTOR_FORBIDDEN';
    end if;

    actor_type_value := 'profile';
    bucket_key := 'operational-task-transcription:profile:' || p_actor_profile_id::text;
    max_attempts := 30;
  else
    select contact.name, access_link.role
    into actor_name_value, access_role
    from public.organization_contacts contact
    join public.task_access_links access_link
      on access_link.contact_id = contact.id
     and access_link.org_id = contact.org_id
    where contact.id = p_actor_contact_id
      and contact.org_id = p_org_id
      and contact.is_active = true
      and access_link.id = p_actor_access_link_id
      and access_link.role in ('assignee', 'delegator')
      and access_link.revoked_at is null
      and access_link.expires_at > now();

    if not found
      or not public.task_access_link_covers(
        p_actor_access_link_id,
        p_task_id,
        p_actor_contact_id
      )
      or (
        access_role = 'assignee'
        and task_row.assignee_contact_id is distinct from p_actor_contact_id
      )
    then
      raise exception using errcode = '42501', message = 'TASK_TRANSCRIPTION_ACTOR_FORBIDDEN';
    end if;

    actor_type_value := 'contact';
    bucket_key := 'operational-task-transcription:contact:' || p_actor_contact_id::text;
    max_attempts := 10;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(bucket_key, 0)
  );

  if actor_type_value = 'profile' then
    select count(*)
    into current_attempts
    from public.task_events event
    where event.event_type = 'transcription_requested'
      and event.actor_profile_id = p_actor_profile_id
      and event.created_at >= now() - interval '1 hour';
  else
    select count(*)
    into current_attempts
    from public.task_events event
    where event.event_type = 'transcription_requested'
      and event.actor_contact_id = p_actor_contact_id
      and event.created_at >= now() - interval '1 hour';
  end if;

  if current_attempts >= max_attempts then
    raise exception using errcode = 'P0001', message = 'TASK_RATE_LIMITED';
  end if;

  insert into public.task_events (
    org_id,
    task_id,
    event_type,
    actor_type,
    actor_profile_id,
    actor_contact_id,
    actor_access_link_id,
    actor_name,
    message,
    metadata
  )
  values (
    p_org_id,
    p_task_id,
    'transcription_requested',
    actor_type_value,
    p_actor_profile_id,
    p_actor_contact_id,
    p_actor_access_link_id,
    actor_name_value,
    'Taltranskribering begärdes.',
    jsonb_build_object(
      'taskMutationApplied', true,
      'byteSize', p_byte_size
    )
  )
  returning * into event_row;

  return event_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.renoapp_guard_rules_acceptance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare required_version uuid;
begin
  if tg_op = 'UPDATE' and (old.status <> 'draft' or old.rules_checked_at is not null) then
    if new.status = 'draft' then raise exception 'CASE_LOCKED'; end if;
    if row(new.rules_version_id, new.rules_accepted_at, new.rules_accepted_name, new.rules_accepted_email, new.rules_checked_at)
      is distinct from row(old.rules_version_id, old.rules_accepted_at, old.rules_accepted_name, old.rules_accepted_email, old.rules_checked_at)
      or new.brf_id <> old.brf_id then raise exception 'RULES_ACCEPTANCE_IMMUTABLE'; end if;
    return new;
  end if;
  if new.status = 'draft' then
    new.rules_version_id := null;
    new.rules_accepted_at := null;
    new.rules_accepted_name := null;
    new.rules_accepted_email := null;
    new.rules_checked_at := null;
    return new;
  end if;
  select renovation_rules_version_id into required_version from public.brf_associations
    where id = new.brf_id for update;
  if new.rules_version_id is distinct from required_version then raise exception 'RULES_VERSION_CHANGED'; end if;
  if required_version is not null then
    if new.rules_accepted_at is null or coalesce(btrim(new.rules_accepted_name), '') = ''
      or coalesce(btrim(new.rules_accepted_email), '') = '' then raise exception 'RULES_ACCEPTANCE_REQUIRED'; end if;
    new.rules_accepted_at := now();
  else
    new.rules_accepted_at := null;
    new.rules_accepted_name := null;
    new.rules_accepted_email := null;
  end if;
  new.rules_checked_at := now();
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.renoapp_lock_decision_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare current_status text;
begin
  if tg_op='INSERT' then
    -- The case lock serializes decisions, including inserts outside the RPC.
    select status into current_status from public.renovation_cases where id=new.case_id for update;
    if current_status='draft' then raise exception 'DRAFT_CASE_LOCKED'; end if;
    if exists(select 1 from public.renovation_case_decisions where case_id=new.case_id) then
      raise exception 'CASE_DECISION_LOCKED';
    end if;
    return new;
  end if;
  if tg_op='DELETE' then
    -- Preserve case deletion/cascades; deleting just the decision is not an undo.
    if exists(select 1 from public.renovation_cases where id=old.case_id) then
      raise exception 'CASE_DECISION_LOCKED';
    end if;
    return old;
  end if;
  if row(new.id,new.case_id,new.decision,new.conditions,new.reason,new.decided_at,new.created_at)
    is distinct from row(old.id,old.case_id,old.decision,old.conditions,old.reason,old.decided_at,old.created_at)
    or (new.decided_by is distinct from old.decided_by and new.decided_by is not null)
  then raise exception 'CASE_DECISION_LOCKED'; end if;
  if old.email_payload is not null and new.email_payload is distinct from old.email_payload then
    raise exception 'DECISION_EMAIL_PAYLOAD_LOCKED';
  end if;
  if old.delivery_status='sent' and new.delivery_status<>'sent' then
    raise exception 'DECISION_EMAIL_ALREADY_SENT';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.renoapp_lock_final_case_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
